<script setup>
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { useQuasar } from 'quasar'
import { api } from '../boot/axios'
import PageHeader from '../components/PageHeader.vue'
import { useAuthStore } from '../stores/auth'

const $q=useQuasar()
const auth=useAuthStore()
const rows=ref([]),clients=ref([]),users=ref([]),loading=ref(false),saving=ref(false),dialog=ref(false),editing=ref(null),search=ref(''),logoFile=ref(null)
const empty=()=>({cliente_id:null,usuario_id:null,nombre_comercial:'',razon_social:'',actividad:'',telefono:'',whatsapp:'',ciudad:'',direccion:'',observaciones:'',estado:'prospecto'})
const form=reactive(empty())
const activeCount=computed(()=>rows.value.filter(x=>x.estado==='activo').length)
const isSuperAdmin=computed(()=>auth.user?.rol==='superadmin')
function owner(row){const u=(row?.usuarios||[]).find(item=>item?.pivot?.rol_negocio==='propietario'&&item?.pivot?.activo!==false);if(!u)return null;return {...u,nombre_completo:[u.nombre,u.apellido].filter(Boolean).join(' ')||u.usuario}}
function userLabel(user){const name=[user.nombre,user.apellido].filter(Boolean).join(' ')||user.usuario;return `${name} · @${user.usuario}`}
async function load(){loading.value=true;try{const [e,c,u]=await Promise.all([api.get('/empresas',{params:{buscar:search.value,per_page:100}}),api.get('/clientes',{params:{per_page:100}}),isSuperAdmin.value?api.get('/usuarios',{params:{per_page:100}}).catch(()=>({data:{data:[]}})):Promise.resolve({data:{data:[]}})]);rows.value=e.data.data||[];clients.value=c.data.data||[];users.value=(u.data.data||[]).filter(user=>user.estado==='activo'&&user.rol==='cliente'&&user.cliente_id)}catch(error){$q.notify({type:'negative',message:error?.response?.data?.message||'No se pudieron cargar las empresas.'})}finally{loading.value=false}}
function open(row=null){editing.value=row;Object.assign(form,empty(),row||{});form.usuario_id=owner(row)?.id||null;dialog.value=true;logoFile.value=null}
async function save(){if(saving.value||!form.nombre_comercial.trim())return;saving.value=true;try{let id;const payload={...form};delete payload.usuario_id;if(editing.value){id=editing.value.id;await api.put(`/empresas/${id}`,{...payload,usuario_id:form.usuario_id})}else{const created=(await api.post('/empresas',payload)).data.data;id=created.id;if(form.usuario_id)await api.put(`/empresas/${id}`,{...payload,usuario_id:form.usuario_id})}if(logoFile.value){const fd=new FormData();fd.append('logo',logoFile.value);await api.post(`/empresas/${id}/logo`,fd)}$q.notify({type:'positive',message:editing.value?'Empresa actualizada.':'Empresa registrada.'});dialog.value=false;await load()}catch(e){$q.notify({type:'negative',message:e.response?.data?.message||'No se pudo guardar.'})}finally{saving.value=false}}
function remove(row){$q.dialog({title:'Eliminar empresa',message:`¿Eliminar ${row.nombre_comercial}?`,cancel:true}).onOk(async()=>{try{await api.delete(`/empresas/${row.id}`);await load();$q.notify({type:'positive',message:'Empresa eliminada.'})}catch(e){$q.notify({type:'negative',message:e.response?.data?.message||'No se puede eliminar.'})}})}
function stateColor(v){return {activo:'positive',desarrollo:'blue',levantamiento:'orange',prospecto:'grey',inactivo:'grey'}[v]||'grey'}
onMounted(load);watch(search,()=>{clearTimeout(window.__vitiCompanySearch);window.__vitiCompanySearch=setTimeout(load,350)})
</script>

<template>
<q-page class="viti-page companies-page">
  <PageHeader eyebrow="Clientes" title="Empresas" subtitle="Cada empresa es un espacio independiente para solicitudes, proyectos, sistemas, responsables y plan comercial.">
    <q-btn class="viti-btn viti-btn--primary" unelevated no-caps icon="add_business" label="Nueva empresa" @click="open()"/>
  </PageHeader>

  <section class="company-toolbar q-mb-lg"><q-input v-model="search" outlined dense clearable debounce="250" placeholder="Buscar por nombre o código"><template #prepend><q-icon name="search"/></template></q-input><div class="toolbar-stats"><span><b>{{rows.length}}</b> total</span><span><b>{{activeCount}}</b> activas</span></div></section>
  <q-inner-loading :showing="loading"/>

  <section v-if="!loading&&!rows.length" class="companies-empty"><div class="empty-icon"><q-icon name="business"/></div><div class="section-label">Sin empresas</div><h2>Registra tu primer negocio.</h2><p>Cuando agregues una empresa podrás relacionar sus solicitudes, proyectos, sistemas y responsables desde un solo lugar.</p><q-btn class="viti-btn viti-btn--primary q-mt-md" unelevated no-caps icon="add_business" label="Registrar empresa" @click="open()"/></section>

  <section v-else class="company-grid">
    <article v-for="row in rows" :key="row.id" class="company-card" @click="open(row)">
      <div class="company-head"><q-avatar size="46px" class="company-avatar"><img v-if="row.logo_url" :src="row.logo_url"/><q-icon v-else name="business"/></q-avatar><div class="company-title"><small>{{row.codigo||'SIN CÓDIGO'}}</small><h3>{{row.nombre_comercial}}</h3></div><q-badge outline :color="stateColor(row.estado)">{{row.estado}}</q-badge></div>
      <p>{{row.actividad||'Actividad todavía no definida.'}}</p>
      <div class="company-owner"><q-icon name="person"/><div><small>Responsable</small><b>{{owner(row)?.nombre_completo||row.cliente?.nombre||'Sin asignar'}}</b></div></div>
      <div class="company-metrics"><div><b>{{row.solicitudes_count||0}}</b><span>Solicitudes</span></div><div><b>{{row.proyectos_count||0}}</b><span>Proyectos</span></div><div><b>{{row.aplicaciones_count||0}}</b><span>Sistemas</span></div></div>
      <div class="company-footer"><span>{{row.ciudad||'Ciudad sin definir'}}</span><div><q-btn flat round dense icon="edit" @click.stop="open(row)"/><q-btn flat round dense icon="delete_outline" color="negative" @click.stop="remove(row)"/></div></div>
    </article>
  </section>

  <q-dialog v-model="dialog"><q-card class="viti-dialog company-dialog"><q-card-section class="dialog-head"><div><div class="section-label">{{editing?'Editar empresa':'Nueva empresa'}}</div><div class="text-h5 text-weight-bold">{{editing?'Actualizar empresa':'Registrar una empresa'}}</div><div class="text-caption text-grey-6">{{editing?'Actualiza los datos principales y la información de contacto del negocio.':'Registra los datos principales del negocio para comenzar a organizar su información en VITI.'}}</div></div><q-btn flat round dense icon="close" v-close-popup/></q-card-section><q-separator/><q-card-section><div class="row q-col-gutter-md"><div class="col-12 col-sm-7"><q-input v-model="form.nombre_comercial" outlined label="Nombre del negocio *"/></div><div class="col-12 col-sm-5"><q-input v-model="form.ciudad" outlined label="Ciudad"/></div><div class="col-12"><q-input v-model="form.actividad" outlined label="¿A qué se dedica?"/></div><div class="col-12 col-sm-6"><q-input v-model="form.telefono" outlined label="Celular de contacto"/></div><div class="col-12 col-sm-6"><q-input v-model="form.whatsapp" outlined label="WhatsApp"/></div><div class="col-12"><q-input v-model="form.observaciones" outlined type="textarea" autogrow label="Nota interna (opcional)"/></div><div class="col-12"><q-expansion-item class="company-advanced" icon="tune" dense-toggle label="Datos opcionales" caption="Solo si realmente los necesitas"><div class="q-pa-md row q-col-gutter-md"><div class="col-12 col-sm-7"><q-input v-model="form.razon_social" outlined label="Razón social"/></div><div class="col-12 col-sm-5"><q-select v-model="form.estado" outlined :options="['prospecto','levantamiento','desarrollo','activo','inactivo']" label="Estado"/></div><div class="col-12"><q-input v-model="form.direccion" outlined label="Dirección"/></div><div class="col-12"><q-file v-model="logoFile" outlined accept="image/*" label="Logotipo" clearable/></div><div class="col-12 col-md-6"><q-select v-model="form.cliente_id" outlined emit-value map-options :options="clients.map(c=>({label:`${c.nombre} · ${c.telefono||c.correo||'sin contacto'}`,value:c.id}))" label="Cliente relacionado" clearable/></div><div v-if="isSuperAdmin" class="col-12 col-md-6"><q-select v-model="form.usuario_id" outlined emit-value map-options clearable :options="users.map(u=>({label:userLabel(u),value:u.id}))" label="Propietario del negocio"/></div></div></q-expansion-item></div></div></q-card-section><q-card-actions align="right"><q-btn class="viti-btn viti-btn--ghost" flat no-caps label="Cancelar" v-close-popup :disable="saving"/><q-btn class="viti-btn viti-btn--primary" unelevated no-caps :loading="saving" :label="editing?'Guardar cambios':'Registrar empresa'" :disable="!form.nombre_comercial" @click="save"/></q-card-actions></q-card></q-dialog>
</q-page>
</template>

<style scoped>
.companies-page{padding-top:34px}.company-toolbar{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:12px 14px;border:1px solid var(--viti-border);background:rgba(8,25,45,.58);border-radius:17px}.company-toolbar .q-field{width:min(430px,100%)}.toolbar-stats{display:flex;gap:16px;color:var(--viti-muted);font-size:10px}.toolbar-stats b{color:var(--viti-text);font-size:15px;margin-right:3px}.companies-empty{min-height:400px;border:1px dashed rgba(121,151,181,.34);border-radius:24px;background:rgba(8,25,45,.5);display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:34px}.empty-icon{width:70px;height:70px;border-radius:20px;background:rgba(20,87,184,.12);display:grid;place-items:center;color:#7eb4ff;font-size:31px;margin-bottom:16px}.companies-empty h2{font-size:28px;margin:5px 0}.companies-empty p{color:var(--viti-muted);max-width:590px}.company-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:15px}.company-card{border:1px solid var(--viti-border);background:linear-gradient(180deg,rgba(15,42,71,.82),rgba(9,28,49,.9));border-radius:20px;overflow:hidden;cursor:pointer;transition:.2s ease}.company-card:hover{transform:translateY(-3px);border-color:rgba(242,139,48,.4)}.company-head{display:flex;align-items:center;gap:11px;padding:18px 18px 10px}.company-avatar{background:rgba(20,87,184,.18);color:#7fb4ff;border:1px solid rgba(90,142,210,.2)}.company-title{min-width:0}.company-title small{font-size:9px;color:#8097ae;letter-spacing:.08em}.company-title h3{font-size:16px;margin:2px 0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.company-head>.q-badge{margin-left:auto}.company-card>p{min-height:42px;margin:4px 18px 15px;color:#9fb2c5;font-size:11px;line-height:1.5}.company-owner{display:flex;align-items:center;gap:9px;margin:0 18px 15px;padding:11px;border-radius:12px;background:rgba(255,255,255,.025)}.company-owner>.q-icon{color:#f28b30}.company-owner div{display:grid}.company-owner small{font-size:8px;color:#7890a7;text-transform:uppercase}.company-owner b{font-size:11px;margin-top:2px}.company-metrics{display:grid;grid-template-columns:repeat(3,1fr);border-top:1px solid rgba(102,132,163,.14);border-bottom:1px solid rgba(102,132,163,.14)}.company-metrics>div{padding:12px;text-align:center;border-right:1px solid rgba(102,132,163,.14)}.company-metrics>div:last-child{border-right:0}.company-metrics b,.company-metrics span{display:block}.company-metrics b{font-size:17px}.company-metrics span{font-size:8px;color:#849bb1;margin-top:2px}.company-footer{padding:9px 12px 9px 18px;display:flex;align-items:center;justify-content:space-between}.company-footer>span{font-size:10px;color:#8ba0b4}.viti-dialog{background:#0c2036;color:var(--viti-text);border:1px solid var(--viti-border);border-radius:22px}.company-dialog{width:880px;max-width:95vw}.dialog-head{display:flex;justify-content:space-between;gap:16px}.viti-btn{border-radius:12px;min-height:42px}.viti-btn--ghost{background:rgba(255,255,255,.025)!important;border-color:rgba(158,180,201,.28)!important}.viti-btn--primary{background:linear-gradient(135deg,#1457b8,#1a69cf)!important}.company-advanced{border:1px solid rgba(72,105,138,.24);border-radius:14px;background:rgba(6,20,36,.42);overflow:hidden}
@media(max-width:1050px){.company-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:700px){.companies-page{padding-top:18px}.company-grid{grid-template-columns:1fr}.company-toolbar{align-items:stretch;flex-direction:column}.company-toolbar .q-field{width:100%}.toolbar-stats{justify-content:space-between}}
</style>
